steps.script:
var dst = AIPlayer.request_suggestion(-1, "U_TELEMON_HEAVY_DREADNOUGHT_A").get("_ai_model_destinations").get("m1")
var m = GameState.state.units.U_TELEMON_HEAVY_DREADNOUGHT_A.models[0].duplicate(true)
m["position"] = {"x": float(dst[0]), "y": float(dst[1])}
var nml = {}
for o in GameState.state.board.objectives:
	if o.id == "obj_nml_1":
		nml = o
return MissionManager.model_gap_to_objective_range_px(m, nml) <= 40.0

var d = AIPlayer.request_suggestion(-1, "U_TELEMON_HEAVY_DREADNOUGHT_A")
var r = NetworkIntegration.route_action({"type": "BEGIN_NORMAL_MOVE", "actor_unit_id": "U_TELEMON_HEAVY_DREADNOUGHT_A", "player": 1})
var ph = PhaseManager.current_phase_instance
if ph.has_pending_stratagem_window():
	var w = ph.get_pending_stratagem_window()
	NetworkIntegration.route_action({"type": "DECLINE_WINDOW_STRATAGEM", "player": int(w.get("player", 1)), "window_id": str(w.get("window_id", ""))})
AIPlayer._execute_ai_movement(1, d)
var u = GameState.state.units.U_TELEMON_HEAVY_DREADNOUGHT_A
var p = Vector2(u.models[0].position.x, u.models[0].position.y)
var nml = {}
for o in GameState.state.board.objectives:
	if o.id == "obj_nml_1":
		nml = o
return bool(u.flags.get("moved", false)) and MissionManager.model_gap_to_objective_range_px(u.models[0], nml) <= 40.0
